import type { Sale as SharedSale } from '@shared/types/sale.js'
import { CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { useSalesHistory } from '../hooks/useSalesHistory.js'

// ============================================================================
// Component — Sales History Page
// ============================================================================

export function SalesHistoryPage() {
  const { sales, total, loading, error, voidingId, customerMap, handleVoid } = useSalesHistory()

  // Format currency in cents → display string
  const formatCurrency = (cents: number): string => {
    return new Intl.NumberFormat('en-IE', {
      style: 'currency',
      currency: 'EUR',
      minimumFractionDigits: 2,
    }).format(cents / 100)
  }

  // Format date from ISO timestamp
  const formatDate = (isoString: string): string => {
    return new Date(isoString).toLocaleDateString('en-IE', {
      year: 'numeric',
      month: 'short',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    })
  }

  // Get customer display name or "Walk-in" (hook manages the cache)
  const getCustomerName = (customerId: string | null): string => {
    if (!customerId) return 'Walk-in'
    return customerMap?.[customerId] || customerId
  }

  // Status badge styling
  const statusBadgeClass = (status: SharedSale['status']): string => {
    return status === 'voided'
      ? 'inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400'
      : 'inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400'
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <CardHeader className="pb-2 px-6 pt-4">
        <CardTitle className="text-xl">Sales History</CardTitle>
      </CardHeader>

      {/* Content */}
      <CardContent className="px-6 pb-6 flex-1 overflow-auto">
        {error && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            {error}
          </div>
        )}

        {loading ? (
          <div className="flex items-center justify-center py-16 text-muted-foreground">
            Loading sales...
          </div>
        ) : sales.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-muted-foreground gap-2">
            <p className="text-lg font-medium">No sales yet</p>
            <p className="text-sm">Completed sales will appear here.</p>
          </div>
        ) : (
          <>
            {/* Summary */}
            <div className="mb-4 text-sm text-muted-foreground">
              Showing {sales.length} of {total} total sale(s)
            </div>

            {/* Sales table */}
            <div className="border rounded-lg overflow-hidden">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-muted/50 border-b">
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Sale #</th>
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Date</th>
                    <th className="text-left px-4 py-2 font-medium text-muted-foreground">Customer</th>
                    <th className="text-right px-4 py-2 font-medium text-muted-foreground">Total</th>
                    <th className="text-center px-4 py-2 font-medium text-muted-foreground">Status</th>
                    <th className="text-center px-4 py-2 font-medium text-muted-foreground">Action</th>
                  </tr>
                </thead>
                <tbody>
                  {sales.map((sale) => (
                    <tr key={sale.id} className="border-b last:border-b-0 hover:bg-muted/30 transition-colors">
                      <td className="px-4 py-2 font-mono text-xs">{sale.sale_number}</td>
                      <td className="px-4 py-2 whitespace-nowrap">{formatDate(sale.created_at)}</td>
                      <td className="px-4 py-2">{getCustomerName(sale.customer_id)}</td>
                      <td className="px-4 py-2 text-right font-medium tabular-nums">
                        {formatCurrency(sale.total_gross)}
                      </td>
                      <td className="px-4 py-2 text-center">
                        <span className={statusBadgeClass(sale.status)}>
                          {sale.status === 'voided' ? 'Voided' : 'Completed'}
                        </span>
                      </td>
                      <td className="px-4 py-2 text-center">
                        {sale.status === 'completed' && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleVoid(sale.id)}
                            disabled={voidingId === sale.id}
                            className="text-red-600 hover:text-red-700 dark:text-red-400 dark:hover:text-red-300 h-8 px-2 text-xs"
                          >
                            {voidingId === sale.id ? 'Voiding...' : 'Void'}
                          </Button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
      </CardContent>
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import type { SaleRecord, CustomerNameMap } from '../types.js'
import { fetchSalesList, voidSale } from '../api.js'
import { getCustomerList } from '../../pos/api.js'

// ---------------------------------------------------------------------------
// useSalesHistory — data fetching hook for the sales history page
//
// Encapsulates:
// - Fetching the sales list on mount (with cancellation guard)
// - Customer name lookup cache population
// - Void action with optimistic update
// ---------------------------------------------------------------------------

export interface UseSalesHistoryReturn {
  /** Array of sale records */
  sales: SaleRecord[]
  /** Total count of all sales */
  total: number
  /** Loading state */
  loading: boolean
  /** Error message (null when OK) */
  error: string | null
  /** Currently voiding sale ID (null when idle) */
  voidingId: string | null
  /** Customer lookup cache (id → displayName) */
  customerMap: CustomerNameMap
  /** Void a sale by ID */
  handleVoid: (saleId: string) => Promise<void>
}

export function useSalesHistory(): UseSalesHistoryReturn {
  const [sales, setSales] = useState<SaleRecord[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(true)
  const [voidingId, setVoidingId] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Customer lookup cache (id → displayName)
  const [customerMap, setCustomerMap] = useState<CustomerNameMap>({})

  // Fetch customer list for name lookups via typed API module
  useEffect(() => {
    let cancelled = false
    ;(async () => {
      try {
        const customers = await getCustomerList()
        if (!cancelled) {
          const map: CustomerNameMap = {}
          for (const c of customers) {
            map[c.id] = c.displayName
          }
          setCustomerMap(map)
        }
      } catch {
        // Customer lookup failure is non-fatal — will show "Walk-in" fallback
      }
    })()
    return () => { cancelled = true }
  }, [])

  // Fetch sales list on mount
  useEffect(() => {
    let cancelled = false
    ;(async () => {
      setLoading(true)
      setError(null)
      try {
        const data = await fetchSalesList(50)
        if (!cancelled) {
          setSales(data.sales)
          setTotal(data.total)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to load sales')
        }
      } finally {
        if (!cancelled) setLoading(false)
      }
    })()
    return () => { cancelled = true }
  }, [])

  // Handle void action
  const handleVoid = useCallback(async (saleId: string): Promise<void> => {
    setVoidingId(saleId)
    try {
      await voidSale(saleId)
      // Update the sale in place — only status changes per R13
      setSales((prev) =>
        prev.map((s) => (s.id === saleId ? { ...s, status: 'voided' } : s))
      )
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to void sale')
    } finally {
      setVoidingId(null)
    }
  }, [])

  return { sales, total, loading, error, voidingId, customerMap, handleVoid }
}

import type { SalesListResponse, VoidError } from './types.js'

// ---------------------------------------------------------------------------
// Sales History API — fetches and voids past sales
//
// Calls the server's GET /api/sales and PATCH /api/sales/:id/void endpoints.
// Uses raw fetch (not apiClient) to match the pattern used by checkout.ts,
// since the server returns plain JSON without an envelope wrapper.
// ---------------------------------------------------------------------------

const API_BASE = ''

// ============================================================================
// Fetch Sales List
// ============================================================================

/**
 * Fetch the sales history list.
 *
 * @param limit — Maximum number of recent sales to return (default: 50)
 * @returns Sales list response with array and total count
 */
export async function fetchSalesList(limit = 50): Promise<SalesListResponse> {
  const response = await fetch(`${API_BASE}/api/sales?limit=${limit}`)

  if (!response.ok) {
    throw new Error(`Failed to fetch sales list: ${response.status}`)
  }

  return (await response.json()) as SalesListResponse
}

// ============================================================================
// Void Sale
// ============================================================================

/**
 * Void a completed sale by setting its status to 'voided'.
 *
 * Does NOT reverse stock movements or payments (per domain rule R13).
 * Guards against voiding already-voided sales.
 *
 * @param saleId — UUID of the sale to void
 * @returns Updated sale record with status = 'voided'
 */
export async function voidSale(saleId: string): Promise<void> {
  const response = await fetch(`${API_BASE}/api/sales/${saleId}/void`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
  })

  if (!response.ok) {
    const errorBody = (await response.json().catch(() => ({}))) as VoidError
    throw new Error(errorBody.error ?? `Void failed with status ${response.status}`)
  }
}

